from itertools import product

# Brute force search for magic sequence of length 6
# x[i] = number of times i appears in the sequence

def is_magic(seq):
    n = len(seq)
    for i in range(n):
        if seq.count(i) != seq[i]:
            return False
    return True

# Search through all possible sequences
# Values must be non-negative and sum to n (since each element counts occurrences)
solutions = []
for seq in product(range(7), repeat=6):
    if sum(seq) == 6 and is_magic(seq):  # sum must equal 6 (total count of all digits)
        solutions.append(seq)

print("Solutions found:", solutions)

# Let me broaden the search - remove the sum constraint and check all possibilities
from itertools import product

def is_magic(seq):
    n = len(seq)
    for i in range(n):
        if seq.count(i) != seq[i]:
            return False
    return True

solutions = []
# Values can range from 0 to 6
for seq in product(range(7), repeat=6):
    if is_magic(seq):
        solutions.append(seq)

print("Solutions found:", solutions)
